import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { ProjectStep } from "@/lib/db/schema/project";
import { OnboardingStatus } from "@/lib/db/schema/user";

export type Account = {
  email: string | null;
  picture: string | null;
  onboardingStatus: OnboardingStatus | null;
  onboardingStep: ProjectStep | null;
};

type AccountStore = Account & {
  hydrated: boolean;
  revision: number;
  onboardingTouchedAt: number;
  setAccount: (account: Account, startedAt: number) => void;
  setOnboarding: (
    onboarding: Pick<Account, "onboardingStatus" | "onboardingStep">,
  ) => void;
  clear: () => void;
  bump: () => void;
  setHydrated: () => void;
};

const empty: Account = {
  email: null,
  picture: null,
  onboardingStatus: null,
  onboardingStep: null,
};

export const useAccountStore = create<AccountStore>()(
  persist(
    (set) => ({
      ...empty,
      hydrated: false,
      revision: 0,
      onboardingTouchedAt: 0,
      setAccount: (account, startedAt) =>
        set((state) => {
          const keepOnboarding = state.onboardingTouchedAt > startedAt;
          return {
            email: account.email,
            picture: account.picture,
            onboardingStatus: keepOnboarding
              ? state.onboardingStatus
              : account.onboardingStatus,
            onboardingStep: keepOnboarding
              ? state.onboardingStep
              : account.onboardingStep,
          };
        }),
      setOnboarding: (onboarding) =>
        set({
          ...onboarding,
          onboardingTouchedAt: Date.now(),
        }),
      clear: () => set({ ...empty, onboardingTouchedAt: 0 }),
      bump: () => set((state) => ({ revision: state.revision + 1 })),
      setHydrated: () => set({ hydrated: true }),
    }),
    {
      name: "ff-account",
      skipHydration: true,
      partialize: (state) => ({
        email: state.email,
        picture: state.picture,
        onboardingStatus: state.onboardingStatus,
        onboardingStep: state.onboardingStep,
      }),
    },
  ),
);

export function rememberOnboarding(draft: {
  step: ProjectStep;
  complete: boolean;
}) {
  useAccountStore.getState().setOnboarding({
    onboardingStatus: draft.complete
      ? OnboardingStatus.complete
      : OnboardingStatus.in_progress,
    onboardingStep: draft.step,
  });
}

import type { User } from "firebase/auth";
import {
  useAccountStore,
  type Account,
} from "@/lib/auth/account-store";

let generation = 0;

export async function syncAccount(user: User | null) {
  const id = ++generation;
  const stale = () => id !== generation;

  try {
    if (!user) {
      useAccountStore.getState().clear();
      await fetch("/api/logout");
      return;
    }

    const token = await user.getIdToken();
    if (stale()) return;

    const login = await fetch("/api/login", {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (stale()) return;

    if (!login.ok) {
      useAccountStore.getState().clear();
      return;
    }

    const startedAt = Date.now();
    const response = await fetch("/api/account");
    if (stale()) return;

    const fallback: Account = {
      email: user.email,
      picture: user.photoURL,
      onboardingStatus: null,
      onboardingStep: null,
    };

    if (!response.ok) {
      useAccountStore.getState().setAccount(fallback, startedAt);
      return;
    }

    const profile = (await response.json()) as Partial<Account>;
    if (stale()) return;

    useAccountStore.getState().setAccount(
      {
        email: profile.email ?? user.email,
        picture: profile.picture ?? user.photoURL,
        onboardingStatus: profile.onboardingStatus ?? null,
        onboardingStep: profile.onboardingStep ?? null,
      },
      startedAt,
    );
  } finally {
    if (!stale()) useAccountStore.getState().bump();
  }
}

export function waitForAccountSync(after: number) {
  const current = useAccountStore.getState();
  if (current.revision > after) return Promise.resolve(current);

  return new Promise<ReturnType<typeof useAccountStore.getState>>(
    (resolve, reject) => {
      const timer = window.setTimeout(() => {
        unsubscribe();
        reject(new Error("Couldn't finish signing in."));
      }, 15000);

      const unsubscribe = useAccountStore.subscribe((state) => {
        if (state.revision > after) {
          window.clearTimeout(timer);
          unsubscribe();
          resolve(state);
        }
      });
    },
  );
}

import { NextResponse } from "next/server";
import { requestUser } from "@/lib/auth/request-user";
import { readAccount } from "@/lib/db/users";

export async function GET() {
  const session = await requestUser();
  if (!session) {
    return NextResponse.json({ error: "Sign in required." }, { status: 401 });
  }

  const account = await readAccount(session.userId);
  if (!account) {
    return NextResponse.json({ error: "Account not found." }, { status: 404 });
  }

  return NextResponse.json(account);
}

"use client";

import { useEffect } from "react";
import { onAuthStateChanged } from "firebase/auth";
import { syncAccount } from "@/lib/auth/sync-account";
import { useAccountStore } from "@/lib/auth/account-store";
import { getFirebaseAuth } from "@/lib/firebase/client-app";

export function AuthProvider({ children }: { children: React.ReactNode }) {
  useEffect(() => {
    let unsubscribe = () => {};
    let cancelled = false;

    void useAccountStore.persist.rehydrate().finally(() => {
      if (cancelled) return;
      useAccountStore.getState().setHydrated();
      unsubscribe = onAuthStateChanged(getFirebaseAuth(), (user) => {
        void syncAccount(user);
      });
    });

    return () => {
      cancelled = true;
      unsubscribe();
    };
  }, []);

  return children;
}

"use client";

import Link from "next/link";
import { ArrowUpRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useAccountStore } from "@/lib/auth/account-store";

export function AuthCta({
  signedOutLabel,
  variant,
  size,
  className,
}: {
  signedOutLabel: string;
  variant: "ink" | "hero";
  size?: "lg";
  className?: string;
}) {
  const signedIn = useAccountStore(
    (state) => state.hydrated && Boolean(state.email),
  );

  return (
    <Button
      nativeButton={false}
      render={<Link href={signedIn ? "/dashboard" : "/auth"} />}
      variant={variant}
      size={size}
      className={className}
    >
      {signedIn ? "Go to dashboard" : signedOutLabel} <ArrowUpRight />
    </Button>
  );
}

