const onboardingStatuses = new Set<string>(Object.values(OnboardingStatus));
const onboardingSteps = new Set<string>(projectSteps);

function onboardingStatus(value: unknown) {
  return onboardingStatuses.has(String(value))
    ? (value as OnboardingStatus)
    : null;
}

function onboardingStep(value: unknown) {
  return onboardingSteps.has(String(value)) ? (value as ProjectStep) : null;
}

export async function readAccount(userId: string) {
  const user = await db().collection("users").doc(userId).get();
  if (!user.exists) return null;

  let status =
    onboardingStatus(user.get("onboarding.status")) ??
    OnboardingStatus.not_started;
  let step: ProjectStep | null = null;
  const projectId = user.get("onboarding.projectId");

  if (typeof projectId === "string" && projectId) {
    const project = await db().collection("projects").doc(projectId).get();
    if (project.exists) {
      status =
        onboardingStatus(project.get("onboarding.status")) ?? status;
      step = onboardingStep(project.get("onboarding.step"));
    }
  }

  const email = user.get("email");
  const picture = user.get("image");

  return {
    email: typeof email === "string" ? email : null,
    picture: typeof picture === "string" ? picture : null,
    onboardingStatus: status,
    onboardingStep: step,
  };
}

